  List<int> prefixToSuffix = [];
  for (int i = 0; i < s.length; i++) {
    prefixToSuffix.add(i);
  }

  void search(int left, int right, String word) {
    if (word.length > right - left + 1) {
      return;
    }

    if (word.isEmpty) {
      result.add([s.substring(left, right + 1)]);
      return;
    }

    for (int i = left; i <= right; i++) {
      if (dp[i] && word.length <= s.length - (right - i + 1)) {
        String suffix = s.substring(i);
        int lo = 0;
        int hi = prefixToSuffix.length - 1;
        while (lo < hi) {
          int mid = (lo + hi) >> 1;
          if (prefixToSuffix[mid] < i) {
            lo = mid + 1;
          } else {
            hi = mid;
          }
        }
        String prefix = s.substring(0, prefixToSuffix[lo]);
        String full = prefix + word + suffix;
        search(left + word.length, right + word.length, full);
      }
    }
  }

  for (int i = 1; i <= s.length; i++) {
    if (dp[i]) {
      search(0, i - 1, s.substring(0, i));
    }
  }
  return result;
