List<String> allSegmentations(String word, List<String> wordBreak, List<String> dictionary) {
  if (word.isEmpty) return [];
  if (dictionary.isEmpty) return [];

  List<String> results = [];
  Set<String> wordSet = wordBreak.toSet();

  bool wordBreak(String s, int idx, Map<String, Set<String>> memo, List<String> wordDict) {
    if (idx == s.length) return true;
    if (memo.containsKey(s + '_' + idx.toString())) {
      return memo[s + '_' + idx.toString()]!;
    }

    for (int i = idx; i <= s.length; i++) {
      if (wordBreak(s.substring(idx, i), i + 1, memo, wordDict)) {
        memo[s + '_' + idx.toString()] = true;
        return true;
      }
    }

    memo[s + '_' + idx.toString()] = false;
    return false;
  }

  Map<String, Set<String>> memo = {};
  for (String word in wordBreak) {
    memo[word] = {};
  }

  for (String word in wordBreak) {
    memo[word] = {};
  }

  for (int i = 0; i <= word.length; i++) {
    String key = word + '_' + i.toString();
    if (wordBreak(word.substring(0, i), i + 1, memo, dictionary)) {
      results.add(word + '_' + i.toString());
    }
  }

  return results;
}

int wordBreakMin(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<int> dp = List.filled(s.length + 1, 0x3FFFFFFFFFFFFFFF);
  dp[0] = 0;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (wordSet.contains(s.substring(j, i)) && dp[j] != 0x3FFFFFFFFFFFFFFF) {
        dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
      }
    }
  }

  return dp[s.length] == 0x3FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF ? -1 : dp[s.length];
}

