Map<String, int> fn0(List<String> commands) {
  Map<String, int> stack = {'BEGIN': 0, 'END': 0, 'ADD': 0};
  List<int> temps = [];
  List<String> history = [];

  void pushTemp(int t) {
    temps.add(t);
    stack['ADD'] = stack['ADD']! + 1;
  }

  void popTemp() {
    if (temps.isNotEmpty) {
      int t = temps.removeLast();
      stack['ADD'] = stack['ADD']! - 1;
      if (stack['ADD'] == 0) stack['END'] = stack['END']! + 1;
    }
  }

  List<String> bracketStack = [];

  for (String cmd in commands) {
    if (cmd == 'BEGIN') {
      stack['BEGIN'] = stack['BEGIN']! + 1;
      bracketStack.add('BEGIN');
    } else if (cmd == 'END') {
      if (bracketStack.isNotEmpty) {
        String top = bracketStack.removeLast();
        if (top == 'BEGIN') stack['BEGIN'] = stack['BEGIN']! - 1;
        if (top == 'END') stack['END'] = stack['END']! - 1;
      }
    } else if (cmd == 'UNDO') {
      if (temps.isNotEmpty) {
        popTemp();
      } else if (bracketStack.isNotEmpty) {
        String top = bracketStack.removeLast();
        if (top == 'BEGIN') stack['BEGIN'] = stack['BEGIN']! - 1;
        if (top == 'END') stack['END'] = stack['END']! - 1;
      }
    } else if (cmd.startsWith('ADD')) {
      int t = int.parse(cmd.substring(4));
      pushTemp(t);
      history.add(cmd);
    } else if (cmd == '(' || cmd == '[') {
      bracketStack.add(cmd);
    } else if (cmd == ')' || cmd == ']') {
      if (bracketStack.isNotEmpty) {
        String open = bracketStack.removeLast();
        if (open == '(') stack['BEGIN'] = stack['BEGIN']! + 1;
        if (open == '[') stack['END'] = stack['END']! + 1;
      }
    } else if (cmd == '*' || cmd == '.') {
      if (temps.isNotEmpty) {
        popTemp();
        history.add(cmd);
      }
    } else if (cmd == '/') {
      if (history.isNotEmpty) {
        String lastCmd = history.removeLast();
        if (lastCmd == 'BEGIN') stack['BEGIN'] = stack['BEGIN']! - 1;
        if (lastCmd == 'END') stack['END'] = stack['END']! - 1;
        if (lastCmd.startsWith('ADD')) stack['ADD'] = stack['ADD']! - 1;
      }
    } else if (cmd == '?') {
      history.sort();
      print(history);
    } else {
      print('Unknown command: $cmd');
    }
  }

  int result = stack['BEGIN']! - stack['END']! - stack['ADD']!;
  return result;
}

