    'Q': 0,
    'K': 0,
  };

  for (int i = 0; i < board.length; i++) {
    final String ch = board[i];
    final String? next = i == board.length - 1 ? null : board[i + 1];

    if (ch == '/') {
      continue;
    }

    final Map<String, int> fileCounts = {
      'A': 0,
      'B': 0,
      'C': 0,
      'D': 0,
      'E': 0,
      'F': 0,
      'G': 0,
      'H': 0,
    };

    bool advancing = false;
    bool capturing = false;

    for (int j = i; j >= 0; j--) {
      final String? previous = j == 0 ? null : board[j - 1];

      if (previous == '/') {
        break;
      }

      if (ch == previous) {
        if (next == previous) {
          advancing = true;
          break;
        }
        continue;
      }

      if (ch == '.' && previous == '#') {
        captureFile(fileCounts, previous);
        continue;
      }

