      fileCounts[color] = fileCounts[color]! + 1;

      if (fileCounts[color]! >= counts[color]!) {
        capturing = true;
      }
    }

    if (advancing) {
      counts[ch] = (counts[ch] ?? 0) + 1;
    } else if (capturing) {
      counts[ch] = (counts[ch] ?? 0) - 1;
    }
  }

  final List<int> result = [];
  for (final String color in ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'T', 'Q', 'K']) {
