        if (avg >= 3) {
          grid[r][c] = 4;
        } else if (avg >= 2) {
          grid[r][c] = 3;
        } else if (avg >= 1) {
          grid[r][c] = 2;
        } else {
          grid[r][c] = 1;
        }
      } else {
