List<String> fn0(String shelfCode, List<String> commands) {
  List<String> history = [];
  Set<String> visited = {};
  List<String> results = [];

  void parse(String bracket, int index) {
    if (index == bracket.length) {
      history.add(shelfCode);
      visited.add(shelfCode);
      return;
    }

    if (bracket[index] == '(') {
      int depth = 1;
      String subCode = '';
      for (int i = index + 1; i < bracket.length; i++) {
        if (bracket[i] == '(') {
          depth++;
        } else if (bracket[i] == ')') {
          depth--;
        } else if (depth == 0 && bracket[i] != ',' && bracket[i] != ' ') {
          subCode += bracket[i];
        }
      }

      if (subCode.isEmpty) {
        return;
      }

      parse(subCode, index + 1);
    } else {
      parse(bracket.substring(0, index + 1), index + 1);
    }
  }

  List<String> parseCommands(List<String> commands) {
    List<String> result = [];

    for (String cmd in commands) {
      if (cmd.isEmpty) {
        continue;
      }

      List<String> parts = cmd.split(' ');
      if (parts.length != 2) {
        continue;
      }

      String op = parts[0];
      if (op != '!' && op != '=') {
        continue;
      }

      List<String> codes = parts[1].split(',');
      if (codes.length != 2) {
        continue;
      }

      String expected = codes[0];
      String actual = codes[1];

      if (op == '!') {
        if (visited.contains(actual)) {
          result.add(actual);
        }
      } else if (op == '=') {
        if (visited.contains(expected)) {
          shelfCode = actual;
          visited.add(shelfCode);
          result.add(shelfCode);
        }
      }
    }

    return result;
  }

  parse(shelfCode, 0);
  List<String> parsed = parseCommands(commands);
  results.addAll(parsed);

  visited.sort();
  results.sort();

  return results;
}

