    var pool = <List<int>>[];
    for (var i = 0; i < cell.length; i++) {
      pool.add([i, 0]);
    }
    var ok = true;
    for (var p in pool) {
      for (var j = 0; j < count; j++) {
        p[1]++;
        var n = i + j;
        if (n == cell.length) n = 0;
        var ok2 = true;
        for (var q in pool) {
          if (q[0] == n) {
