  if (rows == 1 && cols == 1) return [target];
  bool isEdge = rows == 1 || cols == 1;
  List<String> matched = [];
  Set<String> visited = {};
  int dist = 0;
  bool hasTarget = false;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      int nr = r, nc = c;
      if (isEdge && r == 0 && c == 0) nr = 1;
      if (isEdge && r == rows - 1 && c == cols - 1) nc = cols - 2;
      String key = '$nr,$nc';
      if (visited.contains(key)) continue;
      visited.add(key);
      int count = 0;
      for (int i = 0; i < target.length; i++) {
        if (grid[nr][nc] != target[i]) count--;
        else count++;
        if (count == target.length) {
          hasTarget = true;
          break;
        }
        nr = (nr + 1) % rows;
        nc = (nc + 1) % cols;
      }
      if (count == target.length) {
        dist = 0;
        String clean = '';
        for (int d = 0; d < target.length; d++) {
          clean += target[d];
        }
        matched.add('$clean:$count');
      } else if (count > 0) {
        dist++;
      }
    }
  }
  if (!hasTarget) return matched;
  List<String> items = [];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c] == target) {
        items.add('$r,$c');
      }
    }
  }
  if (items.isEmpty) return matched;
  List<String> clusters = [];
  List<String> indices = List.generate(items.length, (i) => i.toString());
  indices.sort((a, b) {
    int pA = a.split(',').length - 1, pB = b.split(',').length - 1;
    if (pA != pB) return pB - pA;
    return int.parse(a) - int.parse(b);
  });
  for (int i = 0; i < indices.length; i++) {
    String idx = indices[i];
    List<String> path = [idx];
    List<int> parents = [0];
    int maxLen = 0;
    String last = idx;
    for (int j = 0; j < items.length; j++) {
      if (indices[j] == idx) {
        path.add(items[j]);
        parents.add(i);
        if (j == 0) {
          maxLen = 1;
        } else if (items[j] == last) {
          maxLen++;
        } else {
          maxLen = 1;
        }
        last = items[j];
        if (maxLen > 4) break;
      }
    }
    if (maxLen <= 4) {
      clusters.add(path.join(','));
    }
  }
  List<String> result = matched;
  result.sort();
  result.addAll(clusters);
  return result;
}

