  }

  int n = int.parse(args[0]);
  if (n <= 0) {
    print('N must be a positive integer.');
    return;
  }

  List<List<int>> queens = List.generate(n, (_) => List<int>.filled(n, 0));

  int solutions = 0;

  void solve(int row) {
    if (row == n) {
      solutions++;
      print('Solution $solutions:');
      for (int i = 0; i < n; i++) {
        String rowStr = '';
        for (int j = 0; j < n; j++) {
          if (queens[i][j] == 1) {
            rowStr += 'Q ';
          } else {
            rowStr += '. ';
          }
        }
        print(rowStr);
      }
      print('');
      return;
    }

    for (int col = 0; col < n; col++) {
      bool safe = true;
      for (int i = 0; i < row; i++) {
        if (queens[i][col] == 1) {
          safe = false;
          break;
        }
      }
      if (safe) {
        queens[row][col] = 1;
        solve(row + 1);
      }
    }
  }

  print('Solving N-Queens for N=$n');
  solve(0);

  print('Total solutions: $solutions');
}

