    if (n <= 0) {
      print('Invalid input: N must be a positive integer.');
      print('Usage: dart run script.dart <N>');
      return;
    }
  }

  List<List<int>> board = List.generate(n, (_) => List.filled(n, 0));

  bool isSafe(int row, int col) {

    for (int r = 0; r < row; r++) {
      if (board[row][col] == 1) return false;
    }

    int r = row - 1;
    int c = col - 1;
    while (r >= 0 && c >= 0) {
      if (board[r][c] == 1) return false;
      r--;
      c--;
    }

    int nr = row - 1;
    int nc = col + 1;
    while (nr >= 0 && nc < n) {
      if (board[nr][nc] == 1) return false;
      nr--;
      nc++;
    }

    return true;
  }

  void place(int row) {
    if (row == n) {

      print('Solution ${solutionNumber}:');
      for (int i = 0; i < n; i++) {
        String line = '';
        for (int j = 0; j < n; j++) {
          line += board[i][j] == 1 ? 'Q ' : '  ';
        }
        print(line);
      }
      solutionNumber++;
      return;
    }

    for (int col = 0; col < n; col++) {
      if (isSafe(row, col)) {
        board[row][col] = 1;
        place(row + 1);
        board[row][col] = 0;
      }
    }
  }

  int solutionNumber = 1;
  place(0);

  print('Solving N-Queens for N=$n');
  print('Total solutions: $solutionNumber');
}

