Map<String, int> fn0(List<int> songLengths) {
  if (songLengths.isEmpty) return {'mashupDuration': 0, 'pairCount': 0};
  int minLength = songLengths[0];
  int maxLength = songLengths[0];
  for (int i = 1; i < songLengths.length; i++) {
    if (songLengths[i] < minLength) minLength = songLengths[i];
    if (songLengths[i] > maxLength) maxLength = songLengths[i];
  }
  int maxPairLength = maxLength - minLength;
  int minPairLength = 2 * minLength - maxPairLength;
  if (maxPairLength < minPairLength) minPairLength = maxPairLength;
  int pairCount = 0;
  int currentSum = 0;
  int n = songLengths.length;
  for (int i = 0; i < n; i++) {
    currentSum += songLengths[i];
    for (int j = i + 1; j < n; j++) {
      int possiblePairLength = songLengths[j] - songLengths[i];
      if (possiblePairLength >= minPairLength && possiblePairLength <= maxPairLength) {
        pairCount++;
        if (currentSum > 0 && (j - i) > maxPairLength) {
          currentSum -= songLengths[i];
        }
        break;
      }
    }
  }
  return {'mashupDuration': currentSum, 'pairCount': pairCount};
}

