  }
  int m = durations.length ~/ 2;
  int left = 0;
  int right = m;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (durations[2 * mid] + durations[2 * mid + 1] <
        durations[2 * (mid - 1) + 1] +
        durations[2 * (mid - 1)]) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  int mashupLength = left + 1;
  int pairCount = 0;
  for (int i = 0; i < durations.length; i += 2) {
    if (durations[i] + durations[i + 1] > mashupLength) {
      pairCount++;
    }
  }
  return {'mashupDuration': mashupLength, 'pairCount': pairCount};
}

