Map<String, int> fn0(List<int> beats, int target) {
  if (beats.isEmpty) return {'pairCount': 0, 'mashupDuration': 0};
  int left = 0;
  int right = beats.length - 1;
  int start = -1;
  int end = -1;
  while (left <= right) {
    int mid = (left + right) ~/ 2;
    int targetSum = 0;
    int currentSum = 0;
    int remaining = mid + 1;
    for (int i = mid; i >= 0; i--) {
      targetSum += beats[i];
      currentSum += beats[i];
      if (remaining <= 0) break;
      if (targetSum > target) {
        right = i - 1;
        break;
      }
    }
    if (targetSum == target) {
      start = i;
      end = mid;
      break;
    }
    if (targetSum < target) {
      left = mid + 1;
    } else {
      right = i - 1;
    }
  }
  if (start == -1) return {'pairCount': 0, 'mashupDuration': 0};
  int sum = 0;
  int count = 0;
  int p = start;
  while (p <= end) {
    sum += beats[p];
    count++;
    p++;
  }
  int duration = (end - start + 1) * 1000;
  return {'pairCount': count, 'mashupDuration': duration};
}

