Map<String, int> fn0(List<int> beats) {
  int n = beats.length;
  if (n == 0) {
    return {'pairCount': 0, 'mashupDuration': 0};
  }

  Map<int, int> dp = {0: 0, 1: 1};
  for (int i = 2; i <= n; i++) {
    dp[i] = dp[i - 1] + (beats[i - 2] == beats[i - 1] ? 1 : 0);
  }

  int maxLen = dp[n];
  int minPrefix = dp[1];
  int minSuffix = dp[1];

  for (int i = 2; i <= n; i++) {
    if (beats[i - 2] == beats[i - 1]) {
      if (dp[i] > maxLen) maxLen = dp[i];
      if (dp[i] < minPrefix) minPrefix = dp[i];
    } else {
      if (dp[i] > maxLen) maxLen = dp[i];
      if (dp[i] < minSuffix) minSuffix = dp[i];
    }
  }

  int pairCount = 0;
  for (int len = minPrefix; len <= maxLen; len++) {
    pairCount += (len & (len - 1)) == 0 ? len : 0;
  }

  int mashupDuration = n - minPrefix + maxLen;
  return {'pairCount': pairCount, 'mashupDuration': mashupDuration};
}

