class Quaternion {
  double x;
  double y;
  double z;
  double w;

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.unit() : this(1.0, 1.0, 1.0, 1.0);

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.fromList(List<double> parts)
      : this(parts[0], parts[1], parts[2], parts[3]);

  const Quaternion.fromAxisAngle(double axisX, double axisY, double axisZ, double angle) {
    double cosA = cos(angle / 2);
    double sinA = sin(angle / 2);
    return const Quaternion(
        (axisX * sinA) + (axisY * sinA),
        (axisX * cosA) - (axisY * sinA),
        (axisZ * sinA) + (axisW * cosA),
        (axisZ * cosA) - (axisW * sinA));
  }

  const Quaternion.fromBasis(List<double> basis) {
    return const Quaternion(basis[0], basis[1], basis[2], basis[3]);
  }

  double norm() {
    return sqrt(x * x + y * y + z * z + w * w);
  }

  double conjugate() {
    return const Quaternion(x, y, -z, w);
  }

  Quaternion operator * (const Quaternion other) {
    double x = this.x * other.w - this.w * other.x;
    double y = this.y * other.w - this.w * other.y;
    double z = this.z * other.w - this.w * other.z;
    return const Quaternion(x, y, z, this.w * other.w);
  }

  Quaternion operator ^ (int exponent) {
    Quaternion result = Quaternion.zero();
    double current = this.norm();
    for (int i = 0; i < exponent; i++) {
      result = result + (current * (this - (this * result)));
    }
    return result;
  }

  @override
  bool operator ==(Object other) =>
      other is Quaternion &&
      x == other.x &&
      y == other.y &&
      z == other.z &&
      w == other.w;

  @override
  int get hashCode => x.hashCode ^ y.hashCode ^ z.hashCode ^ w.hashCode;

  @override
  String toString() => 'q1 = $x + $y * i + $z * j + $w * k';
}

