  const QuaternionRotation.identity()
      : this(const Quaternion.unit(), 0.0, 0.0, 0.0, 0.0);

  const QuaternionRotation(this.q1, this.angle, this.axisX, this.axisY, this.axisZ);

  const QuaternionRotation.random()
      : this(const Quaternion.fromAxisAngle(
          (0.5 - 0.25 * rand.nextDouble()),
