      [2 * a * d - 2 * b * c, 2 * b * d - 2 * c * (1.0 - a * a), 1.0 - 2 * b * b - 2 * d * d],
      [0.0, 0.0, 0.0, 1.0],
    ];
    for (int i = 0; i < 4; i++) {
      for (int j = 0; j < 4; j++) {
