  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion.zero() : this(0, 0, 0, 0);

  Quaternion.unit() : this(1, 0, 0, 1);

  Quaternion.random() : this(
    randomDouble(0, 2) - 1,
    randomDouble(0, 2) - 1,
    randomDouble(0, 2) - 1,
    randomDouble(0, 2),
  );

  Quaternion.fromList(List<double> parts) : this(parts[0], parts[1], parts[2], parts[3]);

  @override
  String toString() =>
      '${x.toStringAsFixed(2)} + ${y.toStringAsFixed(2)}i + ${z.toStringAsFixed(2)}j + ${w.toStringAsFixed(2)}k';

  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(double scalar) =>
      Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator *(Quaternion other) {
    double x1 = x, y1 = y, z1 = z, w1 = w;
    double x2 = other.x, y2 = other.y, z2 = other.z, w2 = other.w;
    return Quaternion(
      (y1 * z2 - y2 * z1) * w1 + x1 * w2 + x2 * w3 + z1 * z2,
      (z1 * w2 - z2 * w1) * x1 + y1 * w2 + y2 * w3 + x2 * z2,
      (x1 * w2 - x2 * w1) * y1 + z1 * w2 + z2 * w3 + y2 * x2,
      (w1 * w2 - w3 * w3) * x1 + y1 * x2 + z1 * y2 + x2 * z1,
    );
  }

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  double norm() => sqrt(x * x + y * y + z * z + w * w);

  Quaternion inverse() => conjugate() * (1 / norm());

  Quaternion normalized() => * (1 / norm());

  Quaternion rotate(List<double> axis) {
    double ax = axis[0], ay = axis[1], az = axis[2];
    double angle = sqrt(ax * ax + ay * ay + az * az);
    if (angle == 0) return * this;
    angle = angle.isEven ? angle / 2 : angle * 0.5;
    double sinA = sqrt(1 - angle * angle);
    double x1 = x, y1 = y, z1 = z;
    return Quaternion(
      (x1 * ax + y1 * ay + z1 * az) * cosA + (x1 * ay - y1 * ax + z1 * az) * sinA,
      (x1 * ay + y1 * az - z1 * ax) * cosA + (y1 * az + z1 * ax) * sinA,
      (x1 * az + y1 * ax - z1 * ay) * cosA + (z1 * ax + y1 * ay) * sinA,
      w,
    );
  }
}

