class Quaternion {
  double x = 0.0;
  double y = 0.0;
  double z = 0.0;
  double w = 0.0;

  void set(double x, double y, double z, double w) {
    this.x = x;
    this.y = y;
    this.z = z;
    this.w = w;
  }

  void setIdentity() {
    set(0.0, 0.0, 0.0, 1.0);
  }

  void conjugate() {
    this.x = x;
    this.y = -y;
    this.z = -z;
    this.w = w;
  }

  void invert() {
    this.x = x;
    this.y = y;
    this.z = z;
    this.w = w * -1.0;
  }

  void normalize() {
    double mag = sqrt(x * x + y * y + z * z + w * w);
    this.x = x / mag;
    this.y = y / mag;
    this.z = z / mag;
    this.w = w / mag;
  }

  void scale(double scaleFactor) {
    this.x *= scaleFactor;
    this.y *= scaleFactor;
    this.z *= scaleFactor;
    this.w *= scaleFactor;
  }

  void add(Quaternion other) {
    this.x += other.x;
    this.y += other.y;
    this.z += other.z;
    this.w += other.w;
  }

  void subtract(Quaternion other) {
    this.x -= other.x;
    this.y -= other.y;
    this.z -= other.z;
    this.w -= other.w;
  }

  void multiply(Quaternion other) {
    double tmpX = x * other.w - y * other.z;
    double tmpY = x * other.z + y * other.w;
    double tmpZ = x * other.y - z * other.w;
    double tmpW = x * other.w + z * other.y;

    this.x = tmpX;
    this.y = tmpY;
    this.z = tmpZ;
    this.w = tmpW;
  }

  @override
  String toString() {
    return 'q1 = $x + $y * i + $z * j + $w * k';
  }
}

