  Quaternion.unitX() : this(1.0, 0.0, 0.0, 0.0);

  Quaternion.unitY() : this(0.0, 1.0, 0.0, 0.0);

  Quaternion.unitZ() : this(0.0, 0.0, 1.0, 0.0);

  Quaternion.unitW() : this(0.0, 0.0, 0.0, 1.0);

  Quaternion.random() : this(
    (4 * (Math.random() * 2 - 1)).toDouble(),
    (4 * (Math.random() * 2 - 1)).toDouble(),
    (4 * (Math.random() * 2 - 1)).toDouble(),
    (4 * (Math.random() * 2 - 1)).toDouble(),
  );

  Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  Quaternion.one() : this(1.0, 1.0, 1.0, 1.0);

  double norm() {
    return (x * x + y * y + z * z + w * w) ** (1 / 2);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion inverse() {
    double invW = 1.0 / w;
    return Quaternion(x * invW, y * invW, z * invW, w * invW);
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  Quaternion operator *(Quaternion other) {
    double invW = 1.0 / other.w;
    return Quaternion(
      x * other.w + other.x * w,
      y * other.w + other.y * w,
      z * other.w + other.z * w,
      other.w * x * invW + other.x * y * invW + other.y * z * invW + other.z * w * invW,
    );
  }

  Quaternion operator ^(int rotations) {
    Quaternion q = Quaternion.identity();
    for (int i = 0; i < rotations; i++) {
      q *= Quaternion.unitZ();
    }
    return q;
  }

  Quaternion normalized() {
    double norm = norm();
    if (norm == 0.0) {
      return Quaternion.zero();
    }
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  double toAngle() {
    double angle = 2 * (Math.atan2(z, w) + (y > 0 ? Math.PI / 2.0 : -Math.PI / 2.0));
    double s = norm() * 0.5;
    return angle - s;
  }

  @override
  String toString() {
    return 'q1 = $x + $y*i + $z*j + $w*k';
  }
}

