    0x0D, 0x49, 0x13, 0x9D,
  ]);

  int littleEndianValue = 0;
  int bigEndianValue = 0;

  if (bytes.length == 4) {

    List<int> bytesList = bytes.map((b) => b & 0xFF).toList();

    switch (bytesList[0]) {
      case 0x0D:
        littleEndianValue = bytesList.map((b) => b << 8).fold(0, (sum, b) => sum + b);
        bigEndianValue = bytesList.map((b) => b << 16).fold(0, (sum, b) => sum + b);
        break;
      case 0x9D:
        bigEndianValue = bytesList.map((b) => b << 16).fold(0, (sum, b) => sum + b);
        littleEndianValue = bytesList.map((b) => b << 8).fold(0, (sum, b) => sum + b);
        break;
    }
  } else {
    throw ArgumentError('Must be 4 bytes');
  }

  String hostName = 'Host system is ';
  String endianStr = bytes.length == 4
      ? (bytesList[0] == 0x0D
          ? 'little-endian'
          : 'big-endian')
      : 'unknown';
  hostName += '$endianStr';

  print('Value from little-endian bytes: 0x${littleEndianValue.toRadixString(16).padLeft(4, '0').toUpperCase()}');
  print('Big-endian bytes: ${bytes.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}');
  print('Value from big-endian bytes: 0x${bigEndianValue.toRadixString(16).padLeft(4, '0').toUpperCase()}');

  List<int> bytesLittleToBig = bytes.map((b) => b & 0xFF).toList();
  bytesLittleToBig[0] ^= bytesLittleToBig[3];
  bytesLittleToBig[1] ^= bytesLittleToBig[2];
  bytesLittleToBig[2] ^= bytesLittleToBig[1];
  bytesLittleToBig[3] ^= bytesLittleToBig[0];

  print('Swapped from little to big: ${bytesLittleToBig.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}');

  print('Little-endian bytes: ${bytes.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}');
}

