List<int> fn0(List<List<int>> grid, int maxFrequency) {
  int rows = grid.length;
  if (rows == 0) return [];
  int cols = grid[0].length;
  if (cols == 0) return [];

  List<List<int>> freq = List.generate(
    rows,
    (_) => List.filled(cols, 0),
  );

  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      freq[i][j] = grid[i][j];
    }
  }

  for (int k = 0; k < rows; k++) {
    for (int i = 0; i < rows - k; i++) {
      for (int j = 0; j < cols - k; j++) {
        int sum = 0;
        for (int p = i; p < i + 2 * k; p++) {
          for (int q = j; q < j + 2 * k; q++) {
            sum += freq[p][q];
          }
        }

        int count = 0;
        int base = sum >= maxFrequency ? sum : maxFrequency;
        while (base > 0) {
          count += base & 1;
          base >>= 1;
        }

        if (count == 1) {
          freq[i][j] = 1;
        }
      }
    }
  }

  return freq;
}

