  int sum = 0;
  for (int i = 0; i < window; i++) {
    sum += heights[i];
    leftSums[i] = sum;
  }

  for (int i = window; i < heights.length; i++) {
    sum += heights[i] - heights[i - window];
    leftSums[i] = sum;
  }

