    final Map<String, String> parent = <String, String>{};
    for (var role in roles.keys) {
      final List<String> permissions = roles[role]!;
      var parentRole = '';
      for (var permission in permissions) {
        if (permissions.contains(permission)) {
          parentRole = permission;
          break;
        }
      }
      parent[role] = parentRole;
    }
    return parent;
  }

