    'alice': ['user', 'viewer', 'editor'],
    'bob': ['user', 'viewer'],
    'charlie': ['user', 'editor'],
    'diana': ['admin'],
  };

  final Map<String, Map<String, List<int>>> rolePermissions = {
    'user': {
      'read': true,
      'write': false,
      'delete': false,
    },
    'viewer': {
      'read': true,
      'write': false,
      'delete': false,
    },
    'editor': {
      'read': true,
      'write': true,
      'delete': false,
    },
    'admin': {
      'read': true,
      'write': true,
      'delete': true,
      'admin': true,
    },
  };

  final Map<String, List<Map<String, List<int>>> resourcePermissions = {
    'document1': {
      'read': true,
      'write': false,
      'delete': false,
    },
    'document2': {
      'read': true,
      'write': true,
      'delete': false,
    },
    'sensitive_data': {
      'read': true,
      'write': false,
      'delete': false,
    },
  };

  final Map<String, Map<String, List<int>>> permissionInheritance = {
    'editor': {
      'read': true,
      'write': true,
      'delete': false,
    },
    'admin': {
      'read': true,
      'write': true,
      'delete': true,
      'admin': true,
    },
  };

  final Map<String, List<String>> userAccessMatrix = {
    'alice': ['document1', 'document2'],
    'bob': ['document1', 'document2'],
    'charlie': ['document1'],
    'diana': ['sensitive_data'],
  };

  final Map<String, Map<String, List<int>>> roleHierarchy = {
    'admin': ['editor', 'viewer', 'user'],
    'editor': ['viewer', 'user'],
    'viewer': ['user'],
  };

  Map<String, List<int>> _flattenPermissions(
      Map<String, List<int>> permissions, List<String> roles) {
    final Map<String, int> result = {};
    for (final role in roles) {
      final Map<String, List<int>> nested = permissions[role] ?? {};
      nested.forEach((action, allowed) {
        result[action] = (result[action] ?? 0) + allowed;
      });
    }
    return result;
  }

  Map<String, List<int>> _combinePermissions(
      Map<String, List<int>> a, Map<String, List<int>> b) {
    final Map<String, List<int>> merged = {};
    final Set<String> actions = a.keys.toSet() | b.keys.toSet();
    for (final action in actions) {
      final int allowA = a[action] ?? 0;
      final int allowB = b[action] ?? 0;
      merged[action] = allowA > allowB ? allowA : allowB;
    }
    return merged;
  }

  void _displayMatrix(
      Map<String, List<String>> grid, String header) {
    print('$header:');
    for (final row in grid.entries) {
      final String line = row.key.padRight(15) + ': ';
      final List<String> entries = row.value;
      for (int i = 0; i < entries.length; i++) {
        if (i > 0) line += ', ';
        line += entries[i].padRight(10);
      }
      print(line);
    }
  }

  void _displayHierarchy(Map<String, List<String>> hierarchy) {
    print('Role Hierarchy:');
    hierarchy.forEach((parent, children) {
      print('  $parent -> [${children.join(', ')}]');
    });
  }

  void _displayAudit(Map<String, List<Map<String, String>>> log) {
    print('--- Audit Log ---\n');
    log.forEach((username, entries) {
      print('User "$username":');
      for (final entry in entries) {
        final String timestamp = entry['timestamp']!;
        final String action = entry['action']!;
        final String result = entry['status']!;
        print('  $timestamp: $action → $result');
      }
    });
  }

  void _displayPermissions(
      Map<String, List<int>> permissions, String name) {
    print('Permissions:');
    permissions.forEach((action, allowed) {
      if (allowed) {
        print('  $action: GRANTED (Role: $name)');
      } else {
        print('  $action: DENIED (Role: $name)');
      }
    });
  }

  print('=== Role-Based Access Control System ===\n');

  Map<String, List<int>> _getUserPermissions(String role, String resource) {
    final Map<String, List<int>> result = {};
    final Map<String, List<String>> allRoles = {};
    for (final entry in userRoles.entries) {
      final List<String> roles = entry.value;
      for (final r in roles) {
        if (!allRoles.containsKey(r)) {
          allRoles[r] = [];
        }
        allRoles[r]!.add(entry.key);
      }
    }
    Map<String, List<int>> finalPermissions = rolePermissions[role] ?? {};
    finalPermissions.forEach((action, allowed) {
      if (allowed) {
        final String resourceRole = resource.split(':')[0];
        if (allRoles[resourceRole]!.contains(role)) {
          result[action] = (result[action] ?? 0) + allowed;
        }
      }
    });
    finalMap = _combinePermissions(finalPermissions, permissionInheritance[role] ?? {});
    return finalMap;
  }

  Map<String, List<int>> _getResourcePermissions(String resource, String role) {
    final Map<String, List<int>> result = {};
    final Map<String, List<String>> allRoles = {};
    for (final entry in userRoles.entries) {
      final List<String> roles = entry.value;
      for (final r in roles) {
        if (!allRoles.containsKey(r)) {
          allRoles[r] = [];
        }
        allRoles[r]!.add(entry.key);
      }
    }
    final Map<String, List<int>> finalPermissions = resourcePermissions[resource] ?? {};
    finalPermissions.forEach((action, allowed) {
      if (allowed) {
        final String roleName = role.split(':')[0];
        if (allRoles[roleName]!.contains(role)) {
          result[action] = (result[action] ?? 0) + allowed;
        }
      }
    });
    finalMap = _combinePermissions(finalPermissions, permissionInheritance[role] ?? {});
    return finalMap;
  }

  final Map<String, List<int>> userPermissions = {};
  for (final entry in userAccessMatrix.entries) {
    final String resource = entry.key;
    final List<String> roles = entry.value;
    for (final r in roles) {
      userPermissions[r] = (userPermissions[r] ?? [])..add(1)..add(0);
    }
  }

  final Map<String, List<int>> resourcePermissions = {};
  for (final entry in resourcePermissions.entries) {
    final String resource = entry.key;
    final Map<String, List<int>> perms = entry.value;
    for (final action in perms.keys) {
      resourcePermissions[action] = (resourcePermissions[action] ?? [])
          .add(perms[action] ?? 0)
          .add(0);
    }
  }

  _displayMatrix(userAccessMatrix, 'User/Resource Access Matrix:');

  _displayPermissions(resourcePermissions, 'Resource: document1');
  _displayPermissions(resourcePermissions, 'Resource: document2');
  _displayPermissions(resourcePermissions, 'Resource: sensitive_data');

  Map<String, List<int>> adminPermissions = {};
  final Map<String, List<String>> allRoles = {};
  for (final entry in userRoles.entries) {
    final List<String> roles = entry.value;
    for (final r in roles) {
      if (!allRoles.containsKey(r)) {
        allRoles[r] = [];
      }
      allRoles[r]!.add(entry.key);
    }
  }
  for (final entry in roleHierarchy.entries) {
    final String parent = entry.key;
    final List<String> children = entry.value;
    if (allRoles[parent]!.contains('admin')) {
      adminPermissions = _flattenPermissions(
          adminPermissions, permissionInheritance[parent] ?? {});
    }
  }
  _displayPermissions(adminPermissions, 'Admin:');

  final Map<String, List<int>> alicePermissions = _getUserPermissions(
      'alice', 'document1');
  final Map<String, List<int>> bobPermissions = _getUserPermissions(
      'bob', 'document2');
  final Map<String, List<int>> charliePermissions = _getUserPermissions(
      'charlie', 'sensitive_data');
  final Map<String, List<int>> dianaPermissions = _getUserPermissions(
      'diana', 'document1');

  _displayMatrix(userPermissions, 'User Permissions Overview —–');
  print('  Viewer   -> [read]');
  print('  Editor   -> [read, write]');
  print('  Admin    -> [read, write, delete, admin]');

  print('\n--- Access Control Tests —–');
  final Map<String, List<int>> testRoles = {
    'alice': [1, 1, 1, 1],
    'bob': [1, 1, 1, 0],
    'charlie': [1, 0, 1, 0],
    'diana': [1, 1, 1, 1],
  };

  for (final entry in testRoles.entries) {
    final String role = entry.key;
    final List<int> permissions = entry.value;
    final String resource = role == 'alice' ? 'document1' : (role == 'bob' ? 'document2' : (role == 'charlie' ? 'sensitive_data' : 'admin'));

    Map<String, List<int>> perms = _getResourcePermissions(resource, role);
    final int allowCount = perms.values.reduce((a, b) => a + b);
    final int denyCount = perms.length - allowCount;
    final bool accessGranted = permissions[0];

    print('Attempting to access $resource → $allowCount/$denyCount');
    if (accessGranted) {
      print('  ✅ Access granted');
    } else {
      print('  ❌ Access denied');
    }
  }

  final Map<String, List<String>> editRoles = ['editor', 'admin'];
  final Map<String, List<int>> editResourcePermissions = {
    'document1': [1, 1, 1],
    'document2': [1, 1, 1],
    'sensitive_data': [1, 1, 1],
  };

  print('\n--- Permission Elevation Scenario —–');
  print('Elevating bob to admin role...');
  final Map<String, List<String>> elevated = userRoles;
  elevated['bob'] = ['admin'];
  final Map<String, List<int>> elevatedPermissions = {};
  for (final entry in elevated.entries) {
    final String role = entry.key;
    final List<String> permissions = entry.value;
    final Map<String, List<int>> nested = resourcePermissions[permissions[0]];
    for (final action in nested.keys) {
      elevatedPermissions[action] = (elevatedPermissions[action] ?? [])
          .add(nested[action] ?? 0)
          .add(0);
    }
  }
  _displayPermissions(elevatedPermissions, 'Current role for bob: admin');

  Map<String, List<int>> adminResourcePermissions = {};
  final Map<String, List<String>> allRoles = [];
  for (final entry in userRoles.entries) {
    final List<String> roles = entry.value;
    for (final r in roles) {
      if (!allRoles.contains(r)) {
        allRoles.add(r);
      }
    }
  }
  for (final entry in roleHierarchy.entries) {
    final String parent = entry.key;
    final List<String> children = entry.value;
    if (allRoles.contains(parent)) {
      adminResourcePermissions = _flattenPermissions(
          adminResourcePermissions, permissionInheritance[parent] ?? {});
    }
  }
  _displayPermissions(adminResourcePermissions, 'Admin:');

  final Map<String, List<int>> elevatedResourcePermissions = _getResourcePermissions(
      'admin', 'bob');
  _displayPermissions(elevatedResourcePermissions, 'Attempting to access admin resource again...');

  print('\n=== System Summary ===');
  print('Total Users: ${userRoles.length}');
  print('Total Roles: ${roleHierarchy.length}');
  print('Total Resources: ${resourcePermissions.length}');
  print('Total Permissions: ${adminPermissions.length}');

  print('\nRecent Access Attempts:');
  final Map<String, List<Map<String, String>>> auditLog = {
    'alice': [
      {'timestamp': '2024-01-01 10:00:00', 'action': 'CREATE', 'status': 'SUCCESS'},
      {'timestamp': '2024-01-01 10:15:00', 'action': 'EDIT', 'status': 'SUCCESS'},
    ],
    'bob': [
      {'timestamp': '2024-01-01 10:05:00', 'action': 'VIEW', 'status': 'SUCCESS'},
      {'timestamp': '2024-01-01 10:10:00', 'action': 'DELETE', 'status': 'SUCCESS'},
    ],
  };
  _displayAudit(auditLog);
}

import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<Map<String, int>> userRoles = [
    {'user': 1, 'admin': 0},
    {'user': 1, 'editor': 1},
    {'editor': 1},
    {'admin': 1},
  ];

  const Map<String, List<String>> rolePermissions = {
    'admin': ['read', 'write', 'delete', 'admin'],
    'editor': ['read', 'write'],
    'viewer': ['read'],
    'moderator': ['read', 'write', 'delete'],
  };

  final Map<String, Map<String, Object>> systemData = {
    'users': <String, Map<String, Object>>{},
    'roles': <String, Map<String, Object>>{},
    'resources': <String, Map<String, Object>>{},
    'auditLog': <String, List<String>>{},
  };

  int roleId = 0;

  void createRole(String name, List<String> permissions) {
    Map<String, Object> roleData = {
      'id': roleId,
      'name': name,
      'permissions': permissions,
    };
    systemData['roles']![name] = roleData;
    roleId++;
  }

  void addPermissionToRole(String roleName, String permission) {
    Map<String, Object> role = systemData['roles']![roleName];
    List<String> current = role['permissions'] as List<String>;
    if (!current.contains(permission)) {
      current.add(permission);
      role['permissions'] = current;
      systemData['roles']![roleName] = role;
    }
  }

  void elevateToAdmin(String username) {
    Map<String, Object> user = systemData['users']![username];
    if (user == null) {
      print('User "$username" not found');
      return;
    }
    if (user['admin'] != 1) {
      print('User "$username" is not an admin');
      return;
    }
    List<String> roles = user['roles'] as List<String>;
    roles.add('admin');
    user['roles'] = roles;
    systemData['users']![username] = user;
  }

  void removePermissionFromRole(String roleName, String permission) {
    Map<String, Object> role = systemData['roles']![roleName];
    List<String> current = role['permissions'] as List<String>;
    if (current.contains(permission)) {
      current.remove(permission);
      role['permissions'] = current;
      systemData['roles']![roleName] = role;
    }
  }

  void grantAccess(String resource, String roleName, String action) {
    Map<String, Object> resourceData = systemData['resources']![resource];
    if (resourceData == null || action != 'read' && action != 'write') {
      print('Resource not found or unknown action: $action');
      return;
    }
    Map<String, Object> role = systemData['roles']![roleName];
    if (role == null) {
      print('Role not found');
      return;
    }
    List<String> permissions = role['permissions'] as List<String>;
    bool granted = false;
    for (String permission in permissions) {
      if (permission == action) {
        granted = true;
        break;
      }
    }
    if (granted) {
      print('  ➜ Access GRANTED (Role: $roleName)');
    } else {
      print('  ➜ Access DENIED (Insufficient permissions)');
    }
  }

  void denyAccess(String resource, String roleName) {
    print('  ➜ Access denied');
  }

  void logAccess(String resource, String roleName, String action) {
    Map<String, Object> resourceData = systemData['resources']![resource];
    if (resourceData == null) {
      print('Resource not found');
      return;
    }
    String timestamp = DateTime.now().toString();
    String line = '$timestamp | ${roleName} | ${action} | ${resource}';
    systemData['auditLog']![resource] ??= <String>[];
    systemData['auditLog']![resource]!.add(line);
    print('  ➜ ${action.toUpperCase().padRight(4)} | ${resource.padRight(15)} | ${roleName.padRight(15)}');
  }

  void printUser(String username) {
    Map<String, Object> user = systemData['users']![username];
    if (user == null) {
      print('  ➜ User "$username" not found');
      return;
    }
    List<String> roles = user['roles'] as List<String>;
    print('  ➜ User: $username');
    print('  ➜ Roles: ${roles.join(', ')}');
    print('  ➜ Permissions: ${rolePermissions[roles.join(', ')} ?? "Unknown"}');
  }

  void printResource(String resource) {
    Map<String, Object> resourceData = systemData['resources']![resource];
    if (resourceData == null) {
      print('  ➜ Resource not found');
      return;
    }
    String actions = resourceData['actions'] as String;
    print('  ➜ Resource: $resource');
    print('  ➜ Actions: $actions');
  }

  void printRole(String role) {
    Map<String, Object> roleData = systemData['roles']![role];
    if (roleData == null) {
      print('  ➜ Role "$role" not found');
      return;
    }
    List<String> permissions = roleData['permissions'] as List<String>;
    print('  ➜ Role: $role');
    print('  ➜ Permissions: ${permissions.join(', ')}');
  }

  void printRecentAccess(String resource) {
    List<String> log = systemData['auditLog']![resource];
    if (log == null || log.isEmpty) {
      print('  ➜ No access logs found for $resource');
      return;
    }
    print('  ➜ Recent Access Attempts:');
    for (String line in log) {
      print('    $line');
    }
  }

  void printSystemSummary() {

    print('\n=== System Summary ===\n');
    print('Total Users: ${systemData['users']!.length}');
    print('Total Roles: ${systemData['roles']!.length}');
    print('Total Resources: ${systemData['resources']!.length}');
    print('Total Permissions: ${systemData['auditLog']!.length}');
  }

  void printRoleHierarchy() {
    Map<String, Object> root = systemData['roles']!;
    String indent = '  ';
    void traverse(Map<String, Object> node, String prefix) {
      for (var key in node.keys) {
        if (key == 'id') continue;
        Map<String, Object> child = node[key] as Map<String, Object>;
        if (child.isEmpty) {
          print('$prefix$key: ${child['permissions']}');
        } else {
          print('$prefix$key:');
          traverse(child, '$prefix  ');
        }
      }
    }
    traverse(root, '');
  }

  void testAccessControl() {

    Map<String, Map<String, Object>> testData = {
      'alice': {'admin': 1, 'editor': 1},
      'bob': {'editor': 1},
      'charlie': {'admin': 1, 'editor': 1, 'viewer': 1},
    };

    List<String> resources = ['document1', 'document2', 'sensitive_data'];
    String resource;
    String action;
    String role;
    bool granted;

    for (String username in testData.keys) {
      Map<String, int> permissions = testData[username]!;
      for (String resource in resources) {
        for (String action in ['read', 'write', 'delete']) {
          role = action == 'delete' ? 'admin' : action;
          granted = permissions.containsKey(role) && permissions[role]! == 1;
          if (granted) {
            print('  ➜ Access GRANTED (Role: ${permissions[role]})');
            continue;
          }
          denyAccess(resource, role);
        }
      }
    }

    print('\n--- Access Control Tests ---\n');
    for (String username in testData.keys) {
      printUser(username);
    }
  }

  void printUserPermissionsOverview() {
    print('\n--- User Permissions Overview ---\n');
    Map<String, Object> root = systemData['users']!;
    void traverse(Map<String, Object> user) {
      for (var key in user.keys) {
        if (key == 'id') continue;
        Map<String, Object> child = user[key] as Map<String, Object>;
        print('  ➜ ${key.padRight(15)}:');
        traverse(child);
      }
    }
    traverse(root);
  }

  void printResourceAccessMatrix() {
    print('\n--- Resource Access Matrix ---\n');
    Map<String, Object> root = systemData['resources']!;
    void traverse(Map<String, Object> resource) {
      for (var key in resource.keys) {
        if (key == 'id') continue;
        Map<String, Object> child = resource[key] as Map<String, Object>;
        print('  ➜ ${key.padRight(15)}:');
        if (child.isEmpty) {
          print('    Permissions: ${child['actions']}');
        } else {
          traverse(child);
        }
      }
    }
    traverse(root);
  }

  void testPermissionElevation() {
    Map<String, Object> user = systemData['users']![<String, Object>{}];
    if (user == null) {
      print('User not found');
      return;
    }
    if (user['admin'] != 1) {
      print('User is not an admin');
      return;
    }
    user['admin'] = 0;
    systemData['users']![<String, Object>{}];
    print('Elevated ${user['username']} to admin role...');
    printUser(user['username'] as String);

    String resource = 'admin_resource';
    String action = 'write';
    grantAccess(resource, 'admin', action);

    denyAccess(resource, 'editor');
    printRecentAccess(resource);
  }

  void testPermissionInheritance() {
    createRole('moderator', ['read', 'write', 'delete']);
    addPermissionToRole('moderator', 'edit');
    createRole('editor', ['read', 'write']);
    addPermissionToRole('editor', 'edit');

    Map<String, Object> user = systemData['users']![<String, Object>{}];
    if (user == null) {
      print('User not found');
      return;
    }
    if (user['admin'] != 1) {
      print('User is not an admin');
      return;
    }

    Map<String, int> permissions = systemData['roles']![<String, int>{}];
    print('Role Hierarchy:');
    permissions.forEach((key, value) {
      print('  ${key.padRight(15)}: ${value.toString().padRight(4)}');
    });

    print('\n--- Permission Inheritance Demo ---\n');
    Map<String, Map<String, Object>> testData = {
      'alice': {'admin': 1, 'editor': 1},
      'bob': {'editor': 1},
      'charlie': {'admin': 1, 'editor': 1, 'viewer': 1},
    };

    List<String> resources = ['document1', 'document2', 'sensitive_data'];
    for (String resource in resources) {
      String action = resource == 'sensitive_data' ? 'read' : 'read';
      grantAccess(resource, 'editor', action);
      denyAccess(resource, 'viewer');
    }
    printUserPermissionsOverview();
    printResourceAccessMatrix();
  }

  void testAuditLog() {
    Map<String, Map<String, Object>> testData = {
      'alice': {'admin': 1, 'editor': 1},
      'bob': {'editor': 1},
      'charlie': {'admin': 1, 'editor': 1, 'viewer': 1},
    };

    List<String> resources = ['document1', 'document2', 'sensitive_data'];
    String resource;
    String action;
    String role;
    bool granted;

    for (String username in testData.keys) {
      Map<String, int> permissions = testData[username]!;
      for (String resource in resources) {
        for (String action in ['read', 'write', 'delete']) {
          role = action == 'delete' ? 'admin' : action;
          granted = permissions.containsKey(role) && permissions[role]! == 1;
          if (granted) {
            print('  ➜ Access GRANTED (Role: ${permissions[role]})');
            continue;
          }
          denyAccess(resource, role);
        }
      }
    }

    print('--- Audit Log ---\n');
    Map<String, List<String>> log = systemData['auditLog']!;
    for (String resource in resources) {
      print('  ➜ ${resource.padRight(15)}:');
      for (String line in log[resource]!) {
        print('    $line');
      }
    }
  }

  Map<String, Object> user = systemData['users']![<String, Object>{}];
  if (user == null) {
    print('User not found');
    return;
  }
  if (user['admin'] != 1) {
    print('User is not an admin');
    return;
  }

  Map<String, Object> resource = systemData['resources']![<String, Object>{}];
  if (resource == null) {
    print('Resource not found');
    return;
  }

  List<String> actions = resource['actions'] as List<String>;
  for (String action in actions) {
    if (action == 'edit') {
      print('  ➜ Access GRANTED (Role: admin)');
      continue;
    }
    denyAccess(resource['id'] as String, 'editor');
  }

  print('Attempting to access admin resource...');
  grantAccess('admin_resource', 'admin', 'read');
  print('  ➜ Access GRANTED (Role: admin)');

  print('Attempting to access admin resource again...');
  removePermissionFromRole('admin', 'admin');
  denyAccess('admin_resource', 'admin');
  print('  ➜ Access DENIED (Insufficient permissions)');

  print('Recent Access Attempts:');
  print('  ➜ ${resource['id']}');
  print('  ➜ ${'sensitive_data'}');
  print('  ➜ ${'admin_resource'}');
  print('  ➜ ${'document1'}');

  print('User/Resource Access Matrix:');
  printUser(user['username'] as String);
  printResource(resource['id'] as String);

  print('\n=== System Summary ===\n');
  printSystemSummary();

  print('Role Hierarchy:');
  printRoleHierarchy();
}

