import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {





  const int MIN_PERMISSION = 0;
  const int MAX_PERMISSION = 15;

  const int USER_ROLE = 0;
  const int ADMIN_ROLE = 1;
  const int EDITOR_ROLE = 2;
  const int MODERATOR_ROLE = 3;
  const int VIEWER_ROLE = 4;

  const int READ_PERMISSION = 0;
  const int WRITE_PERMISSION = 1;
  const int DELETE_PERMISSION = 2;
  const int ADMIN_PERMISSION = 3;

  final Map<int, List<String>> permissions = {
    USER_ROLE: [
      [READ_PERMISSION, 'view'],
      [WRITE_PERMISSION, 'edit'],
      [DELETE_PERMISSION, 'delete']
    ],
    ADMIN_ROLE: [
      [READ_PERMISSION, 'view'],
      [WRITE_PERMISSION, 'edit'],
      [DELETE_PERMISSION, 'delete'],
      [ADMIN_PERMISSION, 'admin']
    ],
    EDITOR_ROLE: [
      [READ_PERMISSION, 'view'],
      [WRITE_PERMISSION, 'edit'],
      [DELETE_PERMISSION, 'delete']
    ],
    MODERATOR_ROLE: [
      [READ_PERMISSION, 'view'],
      [WRITE_PERMISSION, 'edit'],
      [DELETE_PERMISSION, 'delete']
    ],
    VIEWER_ROLE: [
      [READ_PERMISSION, 'view']
    ]
  };

  final Map<String, List<String>> users = {
    'alice': [USER_ROLE],
    'bob': [USER_ROLE, EDITOR_ROLE],
    'charlie': [USER_ROLE, MODERATOR_ROLE],
    'diana': [USER_ROLE, VIEWER_ROLE]
  };

  final Map<String, List<String>> roles = {};
  for (final user in users.keys) {
    final Map<String, List<String>> userRoles = {};
    for (final role in users[user]!) {
      userRoles[role] = (userRoles[role] ?? [])..add(user);
    }
    roles[user] = userRoles;
  }

  final Map<String, List<String>> resources = {
    'document1': ['read', 'write', 'delete'],
    'document2': ['read', 'write'],
    'sensitive_data': ['read', 'write', 'delete']
  };

  const int PERMITTED_MASK = 0xFFFFFFFF;
  const int DENIED_MASK = 0x00000000;

  int calculateEffectivePermissions(int role, String resource) {
    final Map<String, List<String>> resourceRoles = resources[resource] ?? [];
    final Map<String, List<String>> userRoles = roles[resource] ?? {};
    final int userEffective = userRoles.containsKey(resource)
        ? userRoles[resource]!
        : [role];
    final int roleEffective = (role == ADMIN_ROLE)
        ? [role]
        : userEffective;
    final int allEffective = <int>[];
    for (final e in roleEffective) {
      for (final r in e) {
        allEffective.add(r);
      }
    }
    final int sharedMask = allEffective.isEmpty
        ? 0
        : (1 << allEffective.length - 1);
    final int roleMask = 1 << role;
    final int resourceMask = 1 << resourceRoles.length - 1;
    final int effectiveMask = sharedMask & resourceMask;
    return PERMITTED_MASK & effectiveMask;
  }

  final Map<String, String> auditLog = <String, String>{};

  bool checkPermission(String user, String resource, String action, int role) {
    final int effective = calculateEffectivePermissions(role, resource);
    if (effective == 0) {
      auditLog['${user}_${resource}_${action}_DENIED'] = 'DENIED';
      return false;
    }
    int mask = effective;
    final int deniedMask = DENIED_MASK;
    while (mask != 0) {
      final int lowest = mask & -mask;
      final int highest = mask & PERMITTED_MASK;
      final int lower = (mask & -mask) & PERMITTED_MASK;
      final int upper = (mask & PERMITTED_MASK) & -mask;
      if (mask == deniedMask) {
        mask = lower;
      } else if (mask == highest) {
        mask = upper;
      } else {
        mask ^= deniedMask;
      }
    }
    if (mask == 0) {
      auditLog['${user}_${resource}_${action}_DENIED'] = 'DENIED';
      return false;
    }
    final int maskBits = mask & PERMITTED_MASK;
    final int activeCount = ((maskBits >> 16) & 0xFFFF) + ((maskBits >> 8) & 0xFF) + (maskBits & 0xFF);
    int logCode = activeCount + (activeCount == 1 ? 1 : 0);
    if (action == 'delete') {
      logCode += 8;
    } else if (action == 'write') {
      logCode += 4;
    } else if (action == 'read') {
      logCode += 2;
    }
    auditLog['${user}_${resource}_${action}_SUCCESS'] = logCode.toString();
    return true;
  }

  void grantAccess(String user, String resource, String action, int role) {
    if (checkPermission(user, resource, action, role)) {
      print('  ➜ Access GRANTED (Role: $role)');
    } else {
      print('  ➜ Access DENIED (Insufficient permissions)');
    }
  }

  void denyAccess(String user, String resource, String action) {
    print('  ➜ Access DENIED (Insufficient permissions)');
  }

  print('=== Role-Based Access Control System ===\n');
  print('Total Users: ${users.length}\n');
  print('Total Roles: ${roles.length}\n');
  print('Total Resources: ${resources.length}\n');
  print('Total Permissions: ${permissions.length}\n');

  print('\n--- User Permissions Overview ---\n');
  for (final user in users.keys) {
    print('User: $user');
    print('Permissions:');
    for (final role in users[user]!) {
      print('  • ${role}: ${permissions[role]}');
    }
    print('\n--- Access Control Tests ---\n');
    for (final role in users[user]!) {
      for (final resource in resources.keys) {
        final Map<String, List<String>> actions = <String, List<String>>{
          'read': ['view'],
          'write': ['edit'],
          'delete': ['remove']
        };
        for (final action in actions[role]!) {
          print('Attempting to $action on $resource...');
          if (role == USER_ROLE) {
            denyAccess(user, resource, action);
          } else if (checkPermission(user, resource, action, role)) {
            grantAccess(user, resource, action, role);
          } else {
            denyAccess(user, resource, action);
          }
        }
      }
    }
  }

  print('\n--- Resource Access Matrix ---\n');
  print('User/Resource Access Matrix:\n');
  for (final resource in resources.keys) {
    final int effective = calculateEffectivePermissions(USER_ROLE, resource);
    final List<String> validRoles = [];
    for (int i = 0; i < 32; i++) {
      if ((effective & (1 << i)) != 0) {
        validRoles.add(i.toString());
      }
    }
    print('  $resource: ${validRoles.isEmpty ? 'No valid roles' : validRoles.join(', ')}');
  }

  print('\n--- Permission Inheritance Demo ---\n');
  final Map<String, List<String>> nestedRoles = {
    'editor': [EDITOR_ROLE, VIEWER_ROLE],
    'moderator': [MODERATOR_ROLE, EDITOR_ROLE]
  };
