    'moderator': ['read', 'write', 'delete'],
    'viewer': ['read'],
  };

  final Map<String, Map<String, List<String>>> permissions = {
    'read': ['user', 'view'],
    'write': ['user', 'edit'],
    'delete': ['user', 'delete'],
    'admin': ['user', 'manage'],
  };

  final Map<String, String> currentUser = {'role': 'viewer'};

  print('=== Role-Based Access Control System ===\n');

  void displayRoles() {
    print('Total Roles: ${roles.length}\n');
    for (var role in roles.keys) {
      print('  ${role.padRight(10)}: ${roles[role].join(', ')}');
    }
  }

  void displayPermissions() {
    print('\nTotal Permissions: ${permissions.length}\n');
    for (var resource in permissions.keys) {
      print('  ${resource.padRight(10)}: ${permissions[resource].join(', ')}');
    }
  }

  void displayUserPermissions(String user) {
    print('\nUser: $user\n');
    print('Permissions: ${permissions[user]['read']}, ${permissions[user]['write']}, ${permissions[user]['delete']}, ${permissions[user]['admin']}');
  }

  void displayRoleHierarchy() {
    print('\nRole Hierarchy:');
    for (var role in roles.keys) {
      var parent = roles[role];
      while (parent != null) {
        print('  ${parent.padRight(10)} -> $role');
        parent = parent[0];
      }
    }
  }

  void grantAccess(String resource, String action) {
    if (resource.isEmpty || action.isEmpty) {
      print('  ❌ Access denied (Invalid resource or action)');
      return;
    }

    var granted = true;
    var role = currentUser['role'];

    if (!permissions.containsKey(resource)) {
      print('  ❌ Resource not found');
      granted = false;
    }

    if (role == 'admin' || role == resource) {
      granted = true;
    } else {
      var resourceParent = permissions[resource];
      while (resourceParent != null) {
        if (resourceParent.contains(role)) {
          granted = true;
          break;
        }
        resourceParent = resourceParent[0];
      }
    }

    if (granted) {
      print('  ✅ Access granted');
    } else {
      print('  ❌ Access denied (Insufficient permissions)');
    }
  }

  void audit(String resource, String action) {
    print('--- Audit Log ---');
    print('User "${currentUser['user']}" ${action} "${resource}" at ${getCurrentTimestamp()}');
  }

  void raiseAccessLevel(String newRole) {
    print('Elevating ${currentUser['user']} to ${newRole} role...');
    currentUser['role'] = newRole;
    print('Current role for ${currentUser['user']} is ${newRole}');
    print('Permissions: ${permissions[newRole]['read']}, ${permissions[newRole]['write']}, ${permissions[newRole]['delete']}, ${permissions[newRole]['admin']}');
  }

  void displayUserPermissionsOverview() {
    print('\n--- User Permissions Overview ---\n');
    for (var user in ['alice', 'bob', 'charlie', 'diana']) {
      displayUserPermissions(user);
    }
  }

