    print('\n--- Resource Access Matrix ---\n');
    for (var resource in permissions.keys) {
      print('  ${resource.padRight(10)}: ${permissions[resource].join(', ')}');
    }
  }

  void displayRecentAccessAttempts() {
    print('\nRecent Access Attempts:');
    for (var entry in auditLog.entries) {
      print('  ${entry.timestamp.padRight(15)}: ${entry.status}');
    }
  }

  final Map<String, List<String>> auditLog = {
    '2024-01-01 10:00:00': ['alice', 'read', 'document1', 'SUCCESS'],
    '2024-01-01 10:05:00': ['bob', 'write', 'document2', 'SUCCESS'],
    '2024-01-01 10:10:00': ['charlie', 'delete', 'sensitive_data', 'SUCCESS'],
    '2024-01-01 10:15:00': ['diana', 'edit', 'content_moderation', 'DENIED'],
  };

  displayRoles();
  displayPermissions();
  displayUserPermissionsOverview();
  displayResourceAccessMatrix();
  displayRecentAccessAttempts();

  print('\n\n--- Permission Inheritance Demo ---\n');
  raiseAccessLevel('editor');

  displayUserPermissionsOverview();
  displayResourceAccessMatrix();

  print('\n\n--- Permission Elevation Scenario ---\n');
  raiseAccessLevel('admin');

  displayUserPermissionsOverview();
  displayResourceAccessMatrix();

  print('\n--- Access Control Tests ---');
  grantAccess('document1', 'read');
  grantAccess('document1', 'write');
  grantAccess('sensitive_data', 'delete');
  grantAccess('content_moderation', 'edit');

  try {
    grantAccess('document2', 'edit');
  } catch (e) {
    print('  ❌ ${e.toString()}');
  }

  print('\nAttempting to access admin resource...');
  grantAccess('admin', 'read');
  grantAccess('admin', 'write');
  grantAccess('admin', 'delete');
  grantAccess('admin', 'admin');

  print('Attempting to access admin resource again...');
  grantAccess('admin', 'edit');
  print('  ✅ Access GRANTED (Role: admin)');

  print('\n=== System Summary ===');
  print('Total Users: ${currentUser.length}');
  print('Total Resources: ${permissions.length}');
  print('Total Roles: ${roles.length}');
