int swapBytes(int value) {
  int swapped = ((value >> 16) & 0xFFFF) | ((value << 16) & 0xFFFF);
  return swapped & 0xFFFFFFFF;
}

int rotateRight(int value, int shift) {
  shift %= 32;
  if (shift == 0) {
    return value & 0xFFFFFFFF;
  }
  return ((value >> shift) | (value << (32 - shift))) & 0xFFFFFFFF;
}

List<int> byteStream(int value) {
  List<int> bytes = [];
  for (int i = 0; i < 4; i++) {
    bytes.add(value >> (i * 8));
  }
  return bytes;
}

