List<int> fn0(List<int> heights, int row, int col, int distance) {
  if (heights.isEmpty) {
    return [];
  }

  int maxLen = 0;
  List<int> dp = List.filled(heights.length, 1);

  for (int r = 0; r < heights.length; r++) {
    for (int c = 0; c < heights.length; c++) {
      if (r == row && c == col) continue;

      int d = (r - row).abs() + (c - col).abs();
      if (d <= distance) {
        if (r > 0) dp[r - 1] = dp[r - 1] > dp[r] + 1 ? dp[r - 1] : dp[r] + 1;
        if (c > 0) dp[c - 1] = dp[c - 1] > dp[c] + 1 ? dp[c - 1] : dp[c] + 1;

        int len = dp[c];
        if (len > maxLen) maxLen = len;
      }
    }
  }

  return maxLen == 0 ? [] : heights.sublist(0, maxLen);
}

