String fn0(List<int> readings, int minLen) {
  int left = 0;
  int sum = 0;
  int bestStart = -1;
  int bestLen = 0;
  for (int right = 0; right < readings.length; right++) {
    sum += readings[right];
    while (right - left + 1 > minLen) {
      sum -= readings[left];
      left++;
    }
    if (right - left + 1 >= minLen) {
      int windowSum = 0;
      for (int i = left; i <= right; i++) {
        windowSum += readings[i];
      }
      if (windowSum > bestSum) {
        bestSum = windowSum;
        bestStart = left;
      }
    }
  }
  if (bestStart == -1) {
    return "No readings";
  } else {
    int windowSum = 0;
    for (int i = bestStart; i <= bestStart + bestLen - 1; i++) {
      windowSum += readings[i];
    }
    return "Day $bestStart: $windowSum cm";
  }
}

